import{_ as e,o as t,c as a,l as i,t as n,N as o}from"./chunks/framework.Gjrf2Eoj.js";const f=JSON.parse('{"title":"passwd | x-cmd man (man5) | password file","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | passwd - password file","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"passwd | x-cmd man (man5) | password file"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | passwd - password file"}]]},"headers":[],"params":{"isMan":true,"man":"passwd","category":"man5","desc":"password file"},"relativePath":"man5/passwd.md","filePath":"man5/passwd.md"}'),r={name:"man5/passwd.md"},l={class:"visually-hidden"},d=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>passwd - password file</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <em>/etc/passwd</em> file is a text file that describes user login accounts for the system. It should have read permission allowed for all users (many utilities, like <strong>ls</strong>(1) use it to map user IDs to usernames), but write access only for the superuser.</p><p>In the good old days there was no great problem with this general read permission. Everybody could read the encrypted passwords, but the hardware was too slow to crack a well-chosen password, and moreover the basic assumption used to be that of a friendly user-community. These days many people run some version of the shadow password suite, where <em>/etc/passwd</em> has an &#39;x&#39; character in the password field, and the encrypted passwords are in <em>/etc/shadow</em>, which is readable by the superuser only.</p><p>If the encrypted password, whether in <em>/etc/passwd</em> or in <em>/etc/shadow</em>, is an empty string, login is allowed without even asking for a password. Note that this functionality may be intentionally disabled in applications, or configurable (for example using the &quot;<strong>nullok</strong>&quot; or &quot;<strong>nonull</strong>&quot; arguments to <strong>pam_unix</strong>(8)).</p><p>If the encrypted password in <em>/etc/passwd</em> is &quot;<em>*NP*</em>&quot; (without the quotes), the shadow record should be obtained from an NIS+ server.</p><p>Regardless of whether shadow passwords are used, many system administrators use an asterisk (*) in the encrypted password field to make sure that this user can not authenticate themself using a password. (But see NOTES below.)</p><p>If you create a new login, first put an asterisk (*) in the password field, then use <strong>passwd</strong>(1) to set it.</p><p>Each line of the file describes a single user, and contains seven colon-separated fields:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name:password:UID:GID:GECOS:directory:shell</span></span></code></pre></div><p>The field are as follows:</p><dl><dt><em>name</em></dt><dd>This is the user&#39;s login name. It should not contain capital letters.</dd><dt><em>password</em></dt><dd>This is either the encrypted user password, an asterisk (*), or the letter &#39;x&#39;. (See <strong>pwconv</strong>(8) for an explanation of &#39;x&#39;.)</dd><dt><em>UID</em></dt><dd>The privileged <em>root</em> login account (superuser) has the user ID 0.</dd><dt><em>GID</em></dt><dd>This is the numeric primary group ID for this user. (Additional groups for the user are defined in the system group file; see <strong>group</strong>(5)).</dd><dt><em>GECOS</em></dt><dd>This field (sometimes called the &quot;comment field&quot;) is optional and used only for informational purposes. Usually, it contains the full username. Some programs (for example, <strong>finger</strong>(1)) display information from this field.</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GECOS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stands</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">General</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Electric</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Comprehensive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Operating</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">System\\</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;, which was renamed to GCOS when GE\\&#39;s large systems</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">division was sold to Honeywell. Dennis Ritchie has reported:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Sometimes we sent printer output or batch jobs to the GCOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">machine. The gcos field in the password file was a place to stash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">the information for the </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\$</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IDENTcard. Not elegant.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span></span></code></pre></div><dl><dt><em>directory</em></dt><dd>This is the user&#39;s home directory: the initial directory where the user is placed after logging in. The value in this field is used to set the <strong>HOME</strong> environment variable.</dd><dt><em>shell</em></dt><dd>This is the program to run at login (if empty, use <em>/bin/sh</em>). If set to a nonexistent executable, the user will be unable to login through <strong>login</strong>(1). The value in this field is used to set the <strong>SHELL</strong> environment variable.</dd></dl><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p><em>/etc/passwd</em></p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>If you want to create user groups, there must be an entry in <em>/etc/group</em>, or no group will exist.</p><p>If the encrypted password is set to an asterisk (*), the user will be unable to login using <strong>login</strong>(1), but may still login using <strong>rlogin</strong>(1), run existing processes and initiate new ones through <strong>rsh</strong>(1), <strong>cron</strong>(8), <strong>at</strong>(1), or mail filters, etc. Trying to lock an account by simply changing the shell field yields the same result and additionally allows the use of <strong>su</strong>(1).</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>chfn</strong>(1), <strong>chsh</strong>(1), <strong>login</strong>(1), <strong>passwd</strong>(1), <strong>su</strong>(1), <strong>crypt</strong>(3), <strong>getpwent</strong>(3), <strong>getpwnam</strong>(3), <strong>group</strong>(5), <strong>shadow</strong>(5), <strong>vipw</strong>(8)</p>`,22);function h(s,p,g,m,c,u){return t(),a("div",null,[i("h1",l,n(s.$params.man),1),d])}const k=e(r,[["render",h]]);export{f as __pageData,k as default};
